async function handleListConversations(
  ws: WebSocket,
  session: ChatSession,
  store: SessionStore,
  history: ConversationHistoryOptions | undefined,
  message: import('../../types/messages.js').ListConversationsMessage
): Promise<void> {
  if (!history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not enabled');
    return;
  }

  if (!store.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Store does not support listing conversations');
    return;
  }

  try {
    const userId = (ws as ExtWebSocket).userId;
    const summaries = await store.listFor(userId, {
      limit: message.limit,
      before: message.before
        ? {
            updatedAt: new Date(message.before.updatedAt),
            sessionId: message.before.sessionId,
          }
        : undefined,
    });

    sendJson(ws, {
      type: 'conversation_list',
      conversations: summaries.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
        entryCount: s.entryCount,
